{
    "id": "spatial-use-{{$timestamp}}",
    "version": "1.0",
    "title": "Use within a country",
    "description": "Use allowed only in the given country",
    "content": {
        "@context": "http://www.w3.org/ns/odrl.jsonld",
        "@type": "Offer",
        "permission": [
            {
                "action": "use",
                "constraint": [
                    {
                        "leftOperand": "spatial",
                        "operator": "eq",
                        "rightOperand": "$country"
                    }
                ]
            }
        ]
    },
    "parameters": {
        "$country": {
            "dataType": "string"
        }
    }
}

{
    "id": "research-in-country-{{$timestamp}}",
    "version": "1.0",
    "kind": "policy",
    "controlPoints": [
        "negotiation",
        "dataplane"
    ],
    "title": "Research within a country",
    "description": "The seeded research policy, only from the given regions.",
    "content": {
        "@include": [
            {
                "@ref": "research-30-days@1.0",
                "with": {
                    "$duration": "$duration"
                }
            }
        ],
        "permission": [
            {
                "action": "read",
                "constraint": [
                    {
                        "@ref": "spatial@1.0",
                        "with": {
                            "$regions": "$regions"
                        }
                    }
                ]
            }
        ]
    },
    "parameters": {
        "$duration": {
            "dataType": "duration",
            "defaultValue": "P30D"
        },
        "$regions": {
            "dataType": "list",
            "defaultValue": [
                "ES"
            ]
        }
    }
}

